import {SHAPES,emptyGrid,tileLayout,tileRows,fits,placements,placeBlock,makeTray,bombGrid,dealTiles,freeTile,matchTiles,tileHint} from './puzzle-rules.js';
const symbols=['Blue vial','Pink vial','Gold vial','Purple vial','Green vial','Blue crystal','Pink crystal','Gold crystal','Green crystal'];
const tileArt=kind=>kind>=5?`<span class="tile-gem block-${kind-4}" aria-hidden="true"></span>`:`<span class="happy-vial happy-${kind}" aria-hidden="true"></span>`;
const clone=value=>structuredClone(value);
function controls(root){return Object.fromEntries([...root.querySelectorAll('[data-tool]')].map(b=>[b.dataset.tool,b]));}
export function startBlocks(root,cb,options={}){
 const startGrid=emptyGrid();let state={grid:startGrid,tray:makeTray(startGrid,Math.random,1),selected:0,score:0,lines:0,chain:0,moves:0},history=[],tools={bomb:3,undo:3,shuffle:3,hint:3},bomb=false,paused=false,alive=true,ended=false,hintCells=[];
 const board=root.querySelector('#block-board'),tray=root.querySelector('#block-tray'),buttons=controls(root);
 const locked=()=>paused||!alive||ended;
 function hud(){cb.hud(state.score,state.lines,state.chain?`${state.chain}×`:'0');for(const [key,b]of Object.entries(buttons)){b.querySelector('b').textContent=tools[key];b.disabled=locked()||tools[key]===0||(key==='undo'&&!history.length);b.classList.toggle('active',key==='bomb'&&bomb);}}
 function render(){const focused=document.activeElement?.dataset.cell;board.innerHTML=state.grid.flatMap((row,r)=>row.map((v,c)=>`<button class="block-cell ${v?'filled block-'+v:''} ${hintCells.some(([rr,cc])=>rr===r&&cc===c)?'suggested':''}" data-cell="${r*8+c}" role="gridcell" tabindex="${Number(focused||0)===r*8+c?0:-1}" aria-label="Row ${r+1}, column ${c+1}: ${v?'occupied':'empty'}"></button>`)).join('');tray.innerHTML=state.tray.map((p,i)=>`<button class="shape-slot ${state.selected===i?'selected':''}" data-shape="${i}" ${!p?'disabled':''} aria-label="${p?`Piece ${i+1}, ${p.shape.length} blocks. Select then tap its top-left square on the board.`:'Used piece'}" aria-pressed="${state.selected===i}">${p?`<span class="shape-preview" style="--cols:${Math.max(...p.shape.map(p=>p[0]))+1};--rows:${Math.max(...p.shape.map(p=>p[1]))+1}">${p.shape.map(([x,y])=>`<i class="block-${p.color}" style="grid-column:${x+1};grid-row:${y+1}"></i>`).join('')}</span>`:'<svg class="icon piece-done" viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>'}</button>`).join('');board.querySelectorAll('[data-cell]').forEach(b=>{const index=Number(b.dataset.cell),r=Math.floor(index/8),c=index%8;b.onclick=()=>place(r,c);b.onpointerenter=()=>preview(r,c);b.onfocus=()=>preview(r,c);b.onkeydown=e=>{let next=index;if(e.key==='ArrowRight')next=Math.min(63,index+1);else if(e.key==='ArrowLeft')next=Math.max(0,index-1);else if(e.key==='ArrowDown')next=Math.min(63,index+8);else if(e.key==='ArrowUp')next=Math.max(0,index-8);else return;e.preventDefault();board.querySelectorAll('[data-cell]').forEach(x=>x.tabIndex=-1);const target=board.querySelector(`[data-cell="${next}"]`);target.tabIndex=0;target.focus();};});tray.querySelectorAll('[data-shape]').forEach(b=>b.onclick=()=>{if(locked())return;state.selected=Number(b.dataset.shape);bomb=false;hintCells=[];render();cb.sound('select');cb.message('Piece selected. Tap its top-left square on the board.');});hud();if(focused!==undefined)board.querySelector(`[data-cell="${focused}"]`)?.focus({preventScroll:true});}
 function preview(r,c){board.querySelectorAll('.ghost').forEach(b=>b.classList.remove('ghost'));if(locked()||bomb)return;const p=state.tray[state.selected];if(!p||!fits(state.grid,p.shape,r,c))return;for(const [x,y]of p.shape)board.querySelector(`[data-cell="${(r+y)*8+c+x}"]`)?.classList.add('ghost');}
 function place(r,c){if(locked())return;if(bomb){const count=state.grid.flatMap((row,rr)=>row.filter((v,cc)=>v&&Math.abs(rr-r)<=1&&Math.abs(cc-c)<=1)).length;if(!count){cb.sound('invalid');cb.message('Choose a square near filled blocks.');return;}history.push(clone(state));state.grid=bombGrid(state.grid,r,c);tools.bomb--;bomb=false;cb.effect('SPACE CLEARED!','blocks');cb.sound('merge');render();return;}const p=state.tray[state.selected];if(!p){cb.sound('invalid');cb.message('Select a piece from the tray first.');return;}const out=placeBlock(state.grid,p.shape,r,c,p.color);if(!out){cb.sound('invalid');cb.message('That piece needs empty squares. Try another spot.');return;}history.push(clone(state));state.grid=out.grid;state.moves++;state.chain=out.lines?state.chain+1:0;state.lines+=out.lines;state.score+=p.shape.length*10+out.lines*100*Math.max(1,state.chain);state.tray[state.selected]=null;hintCells=[];if(state.tray.every(p=>!p))state.tray=makeTray(state.grid,Math.random,1+Math.floor(state.moves/12));state.selected=state.tray.findIndex(Boolean);render();cb.sound(out.lines?'perfect':'drop');cb.message(out.lines?`${out.lines} ${out.lines===1?'line':'lines'} cleared! ${state.chain>1?state.chain+'× chain.':''}`:'Lovely fit. Keep a little space for the next piece.');if(out.lines)cb.effect(out.lines>1?`${out.lines} LINE BLAST!`:'LINE BLAST!','blocks');cb.progress?.({lines:state.lines});if(!state.tray.some(p=>p&&placements(state.grid,p.shape).length)){if(!tools.bomb&&!tools.shuffle)finish();else cb.message('No space for this tray. Use Bomb or Shuffle, or finish from Pause.');}}
 buttons.bomb.onclick=()=>{if(locked()||!tools.bomb)return;bomb=!bomb;hintCells=[];hud();cb.sound('tool');cb.message(bomb?'Tap a square to clear its surrounding 3 × 3 area.':'Select a piece to keep playing.');};
 buttons.undo.onclick=()=>{if(locked()||!history.length||!tools.undo)return;state=history.pop();tools.undo--;bomb=false;hintCells=[];render();cb.sound('undo');cb.message('Last move restored.');};
 buttons.shuffle.onclick=()=>{if(locked()||!tools.shuffle)return;history.push(clone(state));state.tray=makeTray(state.grid,Math.random,1+Math.floor(state.moves/12));state.selected=0;tools.shuffle--;bomb=false;hintCells=[];render();cb.sound('tool');cb.message('Three fresh pieces. Find a new fit.');};
 buttons.hint.onclick=()=>{if(locked()||!tools.hint)return;let best=null;state.tray.forEach((p,i)=>{if(!p)return;for(const [r,c]of placements(state.grid,p.shape)){const out=placeBlock(state.grid,p.shape,r,c,p.color);if(!best||out.lines>best.lines)best={i,r,c,lines:out.lines,shape:p.shape};}});if(!best){cb.sound('invalid');cb.message('Try Bomb or Shuffle to make space.');return;}tools.hint--;state.selected=best.i;bomb=false;hintCells=best.shape.map(([x,y])=>[best.r+y,best.c+x]);render();cb.sound('hint');cb.message(`Place piece ${best.i+1} at row ${best.r+1}, column ${best.c+1}.`);};
 function finish(){if(ended||!alive)return;ended=true;cb.end({score:state.score,lines:state.lines,moves:state.moves,won:false});}
 render();cb.message('Tap a piece, then tap its top-left square on the board.');return {pause(value=true){paused=value;hud();},finish,destroy(){alive=false;},action(){}};
}
export function startMahjong(root,cb,options={}){
 let tiles=dealTiles(tileLayout(options.level),Math.random,Math.min(9,6+Math.floor((options.level||1)/8))),selected=null,history=[],score=0,pairs=0,chain=0,paused=false,alive=true,ended=false,highlight=[],tools={hint:3,undo:3,shuffle:3};const board=root.querySelector('#mahjong-board'),buttons=controls(root),locked=()=>paused||!alive||ended,rows=tileRows(options.level);board.style.aspectRatio=`6 / ${rows}`;board.style.setProperty('--tile-row',`${100/rows}%`);board.style.setProperty('--tile-height',`${115/rows}%`);board.style.setProperty('--tile-lift',`${7.5/rows}%`);
 board.classList.toggle('dense',options.level>=4);
 function render(){const focused=document.activeElement?.dataset.tile;board.innerHTML=tiles.map(t=>{const free=freeTile(t,tiles);return `<button class="mahjong-tile ${free?'free':'covered'} ${selected===t.id?'selected':''} ${highlight.includes(t.id)?'suggested':''}" data-tile="${t.id}" style="--x:${t.x};--y:${t.y};--z:${t.z}" ${!free?'disabled':''} aria-label="${symbols[t.kind]}, layer ${t.z+1}, ${free?'available':'blocked'}" aria-pressed="${selected===t.id}">${tileArt(t.kind)}</button>`;}).join('');board.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>pick(Number(b.dataset.tile)));cb.hud(score,tiles.length/2,chain?`${chain}×`:'0');for(const [k,b]of Object.entries(buttons)){b.querySelector('b').textContent=tools[k];b.disabled=locked()||!tools[k]||(k==='undo'&&!history.length);}if(focused!==undefined)board.querySelector(`[data-tile="${focused}"]`)?.focus({preventScroll:true});}
 function pick(id){if(locked())return;const t=tiles.find(t=>t.id===id);if(!t||!freeTile(t,tiles))return;highlight=[];if(selected===id){selected=null;render();cb.sound('undo');return;}if(selected===null){selected=id;render();cb.sound('select');cb.message(`${symbols[t.kind]} selected. Find its matching open tile.`);return;}const next=matchTiles(tiles,selected,id);if(!next){chain=0;selected=id;render();cb.sound('invalid');cb.message('Match two identical open tiles. One side must be free.');return;}history.push({tiles:clone(tiles),score,pairs,chain});tiles=next;selected=null;pairs++;chain++;score+=100+Math.min(chain,5)*20;render();cb.effect(chain>1?`${chain}× MATCH!`:'PAIR MATCHED!','mahjong');cb.sound('perfect');cb.message('Lovely pair. A little more of the garden revealed.');if(!tiles.length){ended=true;render();setTimeout(()=>{if(alive)cb.end({score,pairs,moves:pairs,won:true});},450);}else if(!tileHint(tiles))cb.message('No clear route remains. Undo a pair or shuffle the open board.');}
 buttons.hint.onclick=()=>{if(locked()||!tools.hint)return;const pair=tileHint(tiles);if(!pair){cb.message('Try Undo or Shuffle to find a fresh route.');return;}tools.hint--;highlight=pair;selected=pair[0];render();cb.sound('hint');cb.message('The glowing pair keeps a path to the finish.');};
 buttons.undo.onclick=()=>{if(locked()||!history.length||!tools.undo)return;const old=history.pop();tiles=old.tiles;score=old.score;pairs=old.pairs;chain=old.chain;selected=null;highlight=[];tools.undo--;render();cb.sound('undo');cb.message('Your last pair is back. Try a different match.');};
 buttons.shuffle.onclick=()=>{if(locked()||!tools.shuffle)return;history.push({tiles:clone(tiles),score,pairs,chain});try{tiles=dealTiles(tiles);}catch{tiles=dealTiles(tiles.map((t,i)=>({...t,x:i%6,y:Math.floor(i/6),z:0})));}selected=null;highlight=[];tools.shuffle--;render();cb.sound('tool');cb.message('Fresh matches, with a route to clear every tile.');};
 render();cb.message('Match two identical tiles with an open side and nothing on top.');return {pause(value=true){paused=value;},finish(){if(!ended&&alive){ended=true;cb.end({score,pairs,moves:pairs,won:false});}},destroy(){alive=false;},action(){}};
}
